  "As poções vão para <b>Consumíveis</b> no inventário e se bebem <b>fora da batalha</b> (na praça, na sala de espera): curam a vida na hora, para não esperar ela voltar sozinha.": "Las pociones van a <b>Consumibles</b> en el inventario y se beben <b>fuera de batalla</b> (en la Plaza, en la sala de espera): curan al instante, para no esperar a que la vida vuelva sola.",
