  "Nenhum título ainda. Eles não vêm de missão: são pódio de ranking ou teimosia contra um chefe.": "Aún no hay títulos. No vienen de misiones: son podios de ranking o terquedad contra un jefe.",
  "Como ganhar cada título": "Cómo ganar cada título",
  "Seja o 1º, 2º ou 3º de uma classe no ranking do site (a XP daquela classe): \"Top 1 Xamã\", \"Top 2 Bárbaro\"… Vale para cada classe e não acende o nome — o nome brilhante é só do ranking geral de XP, que soma a conta inteira.": "Sé el 1º, 2º o 3º de una clase en el ranking del sitio (la XP de esa clase): \"Top 1 Chamán\", \"Top 2 Bárbaro\"… Vale para cada clase y no enciende el nombre — el nombre brillante es solo del ranking general de XP, que suma toda la cuenta.",
