  "Pronto{a}": "Listo{a}",
  "Esse herói está sem vida: espere {a} s ou beba uma poção.": "Ese héroe está sin vida: espera {a} s o bebe una poción.",
  "Escolha os dois heróis": "Elige a los dos héroes",
  "Toque na ordem: o 1º e o 2º.": "Toca en orden: el 1º y el 2º.",
  "São dois: tire um antes de pôr outro.": "Son dos: quita uno antes de poner otro.",
  "Nenhum herói seu pode lutar.": "Ninguno de tus héroes puede luchar.",
  "Você só tem um herói que pode lutar: ele vai sozinho.": "Solo tienes un héroe que puede luchar: va solo.",
  "O <b>1º</b> é o que todos veem; o <b>2º</b> fica em segredo até a luta.": "El <b>1º</b> es el que todos ven; el <b>2º</b> queda en secreto hasta la lucha.",
