  "Inscrever minha dupla": "Inscribir mi dúo",
  "Inscrito com <b>{a}</b> · esperando há <b class=\"arena-relogio\" data-desde=\"{desdeMs}\">{b}</b>. Pode andar pela praça.": "Inscrito con <b>{a}</b> · esperando hace <b class=\"arena-relogio\" data-desde=\"{desdeMs}\">{b}</b>. Puedes andar por la plaza.",
  "Sair da inscrição": "Cancelar inscripción",
  "Você saiu do quadro da Arena.": "Saliste del cuadro de la Arena.",
