  "Você confirmou. Esperando os outros… <b class=\"arena-relogio\" data-prazo=\"{prazoMs}\">{resta} s</b>": "Confirmaste. Esperando a los otros… <b class=\"arena-relogio\" data-prazo=\"{prazoMs}\">{resta} s</b>",
