  "Entrar na fila": "Entrar a la fila",
  "Escolha os dois heróis que vão à guerra, em ordem. {a} escolhe a dupla dele em seguida. As duplas dos adversários só aparecem na batalha.": "Elige a los dos héroes que van a la guerra, en orden. {a} elige su dúo enseguida. Los dúos de los adversarios solo aparecen en la batalla.",
