  "A luta não bateu com a conferência do servidor — a guerra não rendeu XP.": "La lucha no coincidió con la comprobación del servidor — la guerra no dio XP.",
  "A batalha sincronizou por foto e ninguém mandou um registro limpo — a guerra não rendeu XP.": "La batalla se sincronizó por foto y nadie mandó un registro limpio — la guerra no dio XP.",
  "Empate — nenhuma guilda ganha XP.": "Empate — ningún gremio gana XP.",
  "A guerra ficou sem fim conferido (ninguém mandou um registro com o fim em 2 min): vale a vida do ponto em que parou, sem XP.": "La guerra quedó sin final comprobado (nadie mandó un registro con el final en 2 min): vale la vida del punto donde se detuvo, sin XP.",
  "A guerra valeu, mas sem XP: o teto de guerras de hoje (entre essas guildas, ou da guilda) já foi.": "La guerra valió, pero sin XP: el tope de guerras de hoy (entre esos gremios, o del gremio) ya se agotó.",
