  "Campo de PvP": "Campo de PvP",
  "Só com a <b>coroa ligada</b>; lá dentro ela não desliga. <b>Qualquer um pode te atacar sem aviso</b> — e você também. Vale coroa (até 10 níveis de diferença).": "Solo con la <b>corona activada</b>; dentro no se desactiva. <b>Cualquiera puede atacarte sin aviso</b> — y tú también. Vale corona (hasta 10 niveles de diferencia).",
  "Na entrada você escolhe a dupla do Campo, em ordem: o 1º é a sua aparência lá dentro; o 2º fica em segredo até a luta.": "En la entrada eliges el dúo del Campo, en orden: el 1º es tu apariencia allí dentro; el 2º queda en secreto hasta la lucha.",
