  "{a} saiu da arena — vitória por W.O. (o servidor confere a queda).": "{a} salió de la arena — victoria por W.O. (el servidor comprueba la caída).",
  "Você ficou fora da arena — derrota por W.O.: com a queda confirmada, os seus heróis saem com a vida a 0.": "Quedaste fuera de la arena — derrota por W.O.: con la caída confirmada, tus héroes salen con la vida en 0.",
  " e a coroa conta a derrota": " y la corona cuenta la derrota",
