  "Os cenários e personagens em 3D ficam no servidor. Escolha como baixar — dá para mudar depois, nas Configurações.": "Los escenarios y personajes en 3D están en el servidor. Elige cómo descargar — puedes cambiarlo después en Configuración.",
  "Jogar agora": "Jugar ya",
  "Abre na hora. Cada mapa baixa o que precisa na primeira vez e fica guardado no aparelho.": "Abre al instante. Cada mapa descarga lo que necesita la primera vez y queda guardado en el dispositivo.",
