  "Cada abertura baixa o jogo de novo. Guardar ocupa cerca de {a} MB e, do mesmo jeito, é preciso internet para entrar e jogar.": "Cada apertura descarga el juego de nuevo. Guardarlo ocupa unos {a} MB y, de todos modos, hace falta internet para entrar y jugar.",
