  "Não deu para falar com a Google Play neste aparelho. Abra a Play Store, entre com a sua conta Google e tente de novo.": "No se pudo conectar con Google Play en este dispositivo. Abre la Play Store, inicia sesión con tu cuenta de Google e inténtalo de nuevo.",
