  "água": "agua",
  "O chão deste andar: {a}.": "El suelo de este piso: {a}.",
  "{name} pisa numa placa: setas na linha marcada no começo da rodada {aviso}!": "¡{name} pisa una placa: flechas en la línea marcada al comienzo de la ronda {aviso}!",
  "e leva {a} PP.": "y pierde {a} PP.",
  "A runa prende o passo de {name}{a}": "La runa frena el paso de {name}{a}",
  "O chão arde por onde {name} passou.": "El suelo arde por donde pasó {name}.",
  "{name} se refaz parado na poça (+{cura}).": "{name} se recupera quieto en el charco (+{cura}).",
  "O chão rachado cede por baixo do muro: quando o muro cair, ali é buraco.": "El suelo agrietado cede bajo el muro: cuando el muro caiga, ahí habrá un hueco.",
  "O chão rachado desaba e vira buraco.": "El suelo agrietado se derrumba y se vuelve un hueco.",
  "{name} cai no buraco e sobe na beira.": "{name} cae en el hueco y sube al borde.",
  "As setas da placa varrem a linha!": "¡Las flechas de la placa barren la línea!",
  "As setas da placa varrem a linha vazia.": "Las flechas de la placa barren la línea vacía.",
  "O jato de {a} irrompe do chão{b}": "El chorro de {a} irrumpe del suelo{b}",
  "O respiro de {a} ronca: o chão marcado explode no começo da próxima rodada.": "El respiradero de {a} ruge: el suelo marcado explota al comienzo de la próxima ronda.",
  "O chão rachado range: desaba no começo da próxima rodada.": "El suelo agrietado cruje: se derrumba al comienzo de la próxima ronda.",
  "A couraça de {name} cai em pedaços!": "¡La coraza de {name} cae en pedazos!",
  "O vento preso em {name} sopra {a} para longe!": "¡El viento atrapado en {name} sopla {a} lejos!",
  "Câmara escura: quem não é de Fogo só mira a 2 casas no breu. Braseiro aceso clareia; Fogo acende, Água apaga.": "Cámara oscura: quien no es de Fuego solo apunta a 2 casillas en la penumbra. El brasero encendido aclara; Fuego enciende, Agua apaga.",
  "Galeria alagada: entrar na água custa 2 PP (1 para quem é de Água) e a correnteza empurra 1 casa no fim da rodada.": "Galería inundada: entrar al agua cuesta 2 PP (1 para quien es de Agua) y la corriente empuja 1 casilla al final de la ronda.",
  "Pilares vivos: sobem e descem a cada 2 rodadas, com aviso uma rodada antes. Quem está em cima do soquete segura o pilar.": "Pilares vivos: suben y bajan cada 2 rondas, con aviso una ronda antes. Quien está sobre el soquete sostiene el pilar.",
  "Ventania: a rajada empurra 1 casa no fim da rodada e gira a cada 2 rodadas. Feitiço de Ar alcança 1 casa a mais.": "Ventarrón: la ráfaga empuja 1 casilla al final de la ronda y gira cada 2 rondas. Los hechizos de Aire alcanzan 1 casilla más.",
  "A outra bica começa a verter: a correnteza agora corre para o {a}.": "El otro caño empieza a verter: la corriente ahora corre hacia el {a}.",
  "A correnteza vira na próxima rodada: vai correr para o {a}.": "La corriente gira en la próxima ronda: correrá hacia el {a}.",
  "O cata-vento girou: a rajada agora sopra para o {a}.": "La veleta giró: la ráfaga ahora sopla hacia el {a}.",
  "O vento vira na próxima rodada: vai soprar para o {a}.": "El viento gira en la próxima ronda: soplará hacia el {a}.",
  "O braseiro acende: a luz abre o escuro em volta.": "El brasero se enciende: la luz abre la oscuridad alrededor.",
  "O braseiro apaga: o escuro fecha em volta.": "El brasero se apaga: la oscuridad se cierra alrededor.",
  "Os pilares vivos trocam de lugar: {length} de pé, {a} no chão.": "Los pilares vivos cambian de lugar: {length} en pie, {a} abajo.",
  "Um pilar espera: há alguém em cima do soquete.": "Un pilar espera: hay alguien sobre el soquete.",
  "{length} pilares esperam: há alguém em cima dos soquetes.": "{length} pilares esperan: hay alguien sobre los soquetes.",
  "Os pilares vivos tremem: trocam de lugar no começo da próxima rodada.": "Los pilares vivos tiemblan: cambian de lugar al comienzo de la próxima ronda.",
  "A correnteza corre para o {a} e arrasta quem está na água.": "La corriente corre hacia el {a} y arrastra a quien está en el agua.",
  "A correnteza corre para o {a}.": "La corriente corre hacia el {a}.",
  "A rajada sopra para o {a} e empurra quem está no terraço.": "La ráfaga sopla hacia el {a} y empuja a quien está en la terraza.",
  "A rajada sopra para o {a}.": "La ráfaga sopla hacia el {a}.",
