  "Sua conta entrou em outro aparelho. Este jogo foi encerrado aqui.": "Tu cuenta entró en otro dispositivo. Este juego se cerró aquí.",
  "Você saiu desta conta neste navegador.": "Cerraste sesión en esta cuenta en este navegador.",
  "Você saiu desta conta.": "Cerraste sesión en esta cuenta.",
  "A conta saiu em outra aba deste navegador, e este jogo foi encerrado aqui.": "La cuenta cerró sesión en otra pestaña de este navegador, y este juego se cerró aquí.",
  "O progresso está guardado no servidor. Entre de novo para continuar.": "Tu progreso está guardado en el servidor. Inicia sesión de nuevo para continuar.",
  "Outra conta entrou neste navegador.": "Otra cuenta entró en este navegador.",
  "Este jogo era da conta de antes e foi encerrado aqui.": "Este juego era de la cuenta anterior y se cerró aquí.",
  "Recarregue para jogar com a conta que entrou.": "Recarga para jugar con la cuenta que entró.",
  "Este jogo foi encerrado aqui.": "Este juego se cerró aquí.",
  "Uma conta fica aberta em um aparelho por vez. Se não foi você, entre e troque a senha na página da conta.": "Una cuenta se mantiene abierta en un dispositivo a la vez. Si no fuiste tú, entra y cambia la contraseña en la página de la cuenta.",
  "Recarregar": "Recargar",
  "quem troca com você": "quien intercambia contigo",
  "Troca cancelada: o servidor não conferiu a conta de {a}, e peça com número de série só muda de mão pelo cartório. Ela precisa entrar na conta e recarregar a página.": "Intercambio cancelado: el servidor no verificó la cuenta de {a}, y una pieza con número de serie solo cambia de manos por el registro. Debe iniciar sesión y recargar la página.",
  "Troca cancelada: o servidor não conferiu a sua conta nesta conexão. Recarregue a página (F5) e tente de novo.": "Intercambio cancelado: el servidor no verificó tu cuenta en esta conexión. Recarga la página (F5) e inténtalo de nuevo.",
  "Troca cancelada: o cartório não conferiu uma das contas, e peça com número de série só muda de mão por lá. Recarreguem a página e tentem de novo.": "Intercambio cancelado: el registro no verificó una de las cuentas, y una pieza con número de serie solo cambia de manos allí. Recarguen la página e inténtenlo de nuevo.",
  "Troca cancelada: uma peça ou bicho da mesa do outro lado não estava mais com ele.": "Intercambio cancelado: una pieza o mascota de la mesa del otro lado ya no estaba con esa persona.",
  "Troca cancelada: o saco do outro lado não tinha espaço para o que ia.": "Intercambio cancelado: el saco del otro lado no tenía espacio para lo que iba.",
  "Troca cancelada: o outro lado já tem um dos bichos da mesa — é um de cada.": "Intercambio cancelado: el otro lado ya tiene una de las mascotas de la mesa — una de cada una.",
  "Troca cancelada: você já tem o {nome} — é um bicho de cada.": "Intercambio cancelado: ya tienes el {nome} — una mascota de cada una.",
  "Troca cancelada: uma peça que você pôs na mesa não está mais no seu saco.": "Intercambio cancelado: una pieza que pusiste en la mesa ya no está en tu saco.",
  "Troca cancelada: um bicho que você pôs na mesa não está mais solto (foi vestido ou já saiu).": "Intercambio cancelado: una mascota que pusiste en la mesa ya no está suelta (fue equipada o ya salió).",
  "Troca cancelada: o seu saco não tem espaço para o que vem.": "Intercambio cancelado: tu saco no tiene espacio para lo que viene.",
  "A troca não foi registrada no servidor: {a}": "El intercambio no fue registrado en el servidor: {a}",
  "Escolha <b>1 ou 2</b> heróis. Sozinho, a sorte de saque é máxima; em dupla, vocês podem <b>FUNDIR</b> no meio da luta e virar outra coisa.": "Elige <b>1 o 2</b> héroes. En solitario, la suerte del botín es máxima; en dúo, pueden <b>FUSIONARSE</b> en plena lucha y convertirse en otra cosa.",
  "Toque no chão para <b>andar</b>. Chegue perto de um portal para descer, do banco para guardar, da arena para duelar. O <b>cais</b> aí embaixo abre inventário, forja e missões — e a tecla <b>I</b> abre o saco.": "Toca el suelo para <b>caminar</b>. Acércate a un portal para descender, al banco para guardar, a la arena para duelar. El <b>muelle</b> de abajo abre inventario, forja y misiones — y la tecla <b>I</b> abre el saco.",
  "Toque no chão para andar (o segundo toque <b>confirma</b>). Toque num feitiço e depois no alvo. O relógio de <b>30s</b> acumula o que sobrar para os próximos turnos.": "Toca el suelo para caminar (el segundo toque <b>confirma</b>). Toca un hechizo y luego el objetivo. El reloj de <b>30s</b> acumula lo que sobre para los próximos turnos.",
  "O saque já está no <b>saco</b> (tecla I). Os vivos curam metade do que perderam ao avançar — e a próxima sala vem inteira.": "El botín ya está en el <b>saco</b> (tecla I). Los vivos curan la mitad de lo que perdieron al avanzar — y la próxima sala viene entera.",
