  "Sair da tela cheia": "Salir de pantalla completa",
  "<b>Tela cheia</b><p>Este navegador não deixa o jogo ocupar a tela inteira — é o caso do Safari no iPhone.</p><p>O jeito que funciona é instalar o SOTERRA na tela de início e abrir pelo ícone: ele roda sem as barras do navegador, em pé ou deitado.</p><ul><li><b>iPhone e iPad</b> (Safari): Compartilhar → <i>Adicionar à Tela de Início</i></li><li><b>Android</b>: menu ⋮ do navegador → <i>Instalar app</i> ou <i>Adicionar à tela inicial</i></li></ul><button type=\"button\" class=\"btn btn-mini btn-primary tc-ok\">Entendi</button>": "<b>Pantalla completa</b><p>Este navegador no deja que el juego ocupe toda la pantalla — es el caso de Safari en el iPhone.</p><p>Lo que funciona es instalar SOTERRA en la pantalla de inicio y abrirlo desde el ícono: corre sin las barras del navegador, en vertical u horizontal.</p><ul><li><b>iPhone y iPad</b> (Safari): Compartir → <i>Añadir a pantalla de inicio</i></li><li><b>Android</b>: menú ⋮ del navegador → <i>Instalar app</i> o <i>Añadir a la pantalla de inicio</i></li></ul><button type=\"button\" class=\"btn btn-mini btn-primary tc-ok\">Entendido</button>",
  "o servidor está fora do ar ou reiniciando (HTTP {status})": "el servidor está caído o reiniciándose (HTTP {status})",
  "já subindo": "ya está subiendo",
  "a sessão não vale mais": "la sesión ya no es válida",
  "<h2 style=\"color:#ffd98a;font-family:Georgia,serif;margin-bottom:12px\">SOTERRA precisa de WebGL</h2>Seu navegador ou placa de vídeo não conseguiu iniciar o modo 3D.<br>Tente atualizar o navegador, habilitar aceleração de hardware nas configurações, ou usar Chrome/Edge/Firefox recentes.": "<h2 style=\"color:#ffd98a;font-family:Georgia,serif;margin-bottom:12px\">SOTERRA necesita WebGL</h2>Tu navegador o tarjeta de video no pudo iniciar el modo 3D.<br>Prueba actualizar el navegador, activar la aceleración por hardware en la configuración, o usar un Chrome/Edge/Firefox reciente.",
