  "Sem conexão com o servidor do jogo. Confira a internet e tente de novo.": "Sin conexión con el servidor del juego. Revisa tu internet e inténtalo de nuevo.",
  "Não deu para preparar os anúncios neste aparelho. Atualize o aplicativo pela Play Store e tente de novo.": "No se pudieron preparar los anuncios en este dispositivo. Actualiza la aplicación desde Play Store e inténtalo de nuevo.",
