  "A peça com a <b>Gema engastada</b> não funde: a cópia nova nasceria sem o bônus.": "La pieza con la <b>Gema engastada</b> no se fusiona: la copia nueva nacería sin la bonificación.",
  "Gema": "Gema",
  "Engastar a Gema Enterrada": "Engastar la Gema Enterrada",
  "um bônus a mais na peça: +1 PA, +1 PP, dano ou vida — sorteado": "una bonificación extra en la pieza: +1 PA, +1 PM, daño o vida — sorteada",
  "<b>{a}</b> na prateleira · gasta 1": "<b>{a}</b> en el estante · gasta 1",
  "nenhuma — junte {a} fragmentos": "ninguna — junta {a} fragmentos",
  "Já engastada": "Ya engastada",
  "Um destes": "Uno de estos",
  "Ponha uma peça na bancada: arraste da grade abaixo ou toque nela. A gema dá a ela <b>um</b> bônus a mais, sorteado — do mais difícil ao mais fácil: PA, PP, dano, vida. Cada peça aceita uma gema só.": "Pon una pieza en el banco: arrástrala desde la cuadrícula de abajo o tócala. La gema le da <b>una</b> bonificación extra, sorteada — de la más difícil a la más fácil: PA, PM, daño, vida. Cada pieza acepta una sola gema.",
  "A Gema ainda não está disponível.": "La Gema aún no está disponible.",
  "Esta peça <b>já tem a sua Gema</b> ({a}). Cada peça aceita uma só.": "Esta pieza <b>ya tiene su Gema</b> ({a}). Cada pieza acepta una sola.",
  "Sem Gema na prateleira. Você tem <b>{a}</b> de {b} fragmentos para a próxima — eles caem nos seis portais, vêm da loja do site e do anúncio premiado.": "Sin Gema en el estante. Tienes <b>{a}</b> de {b} fragmentos para la próxima — caen en los seis portales, vienen de la tienda del sitio y del anuncio premiado.",
  "Pronto: <b>1 {a}</b> engasta um bônus nesta peça, sorteado na hora. O bônus fica na peça para sempre (vestida ou no saco) — e a peça engastada não vai ao mercadinho, à troca nem ao banco da guilda.": "Listo: <b>1 {a}</b> engasta una bonificación en esta pieza, sorteada al momento. La bonificación queda en la pieza para siempre (puesta o en la bolsa) — y la pieza engastada no va al mercadillo, al intercambio ni al banco del gremio.",
  "{a}: <b>{b}</b> / {c}": "{a}: <b>{b}</b> / {c}",
  "Juntar {a} → 1 gema": "Juntar {a} → 1 gema",
  "Faltam {a} fragmentos.": "Faltan {a} fragmentos.",
  "Uma {a} nova na prateleira ({b}).": "Una {a} nueva en el estante ({b}).",
  "Não deu para juntar os fragmentos.": "No se pudieron juntar los fragmentos.",
