  "◆ Engastar a Gema — gasta 1": "◆ Engastar la Gema — gasta 1",
  "Engastar a Gema?": "¿Engastar la Gema?",
  "Uma {a} some e {qual} ganha <b>um</b> bônus sorteado — PA, PP, dano ou vida. Não tem volta, e a peça não aceita outra.": "Una {a} desaparece y {qual} gana <b>una</b> bonificación sorteada — PA, PM, daño o vida. No hay vuelta atrás, y la pieza no acepta otra.",
  "Engastar": "Engastar",
