  "◆ A Gema deu <b>{a}</b> à peça!": "◆ ¡La Gema le dio <b>{a}</b> a la pieza!",
  "O servidor não respondeu — nada foi engastado.": "El servidor no respondió — no se engastó nada.",
  "O servidor não engastou agora.": "El servidor no engastó ahora.",
  "O servidor não engastou: o saco mudou. Confira a bancada.": "El servidor no engastó: la bolsa cambió. Revisa el banco.",
  "Opcional: assista a um anúncio e ganhe vinténs, uma barra de ouro ou Fragmentos de Gema. Até 5 de cada por dia. O jogo não mostra anúncio em nenhum outro lugar.": "Opcional: mira un anuncio y gana vinténs, una barra de oro o Fragmentos de Gema. Hasta 5 de cada uno por día. El juego no muestra anuncios en ningún otro lugar.",
  // ---- 08/10: as duas iniciais livres e a estrela comprada com cartas
  "Bem-vindo! Escolha os seus DOIS primeiros heróis, de qualquer classe — o primeiro é o seu avatar e anda no Acampamento. As outras classes vêm depois, pelas cartas dos chefes.": "¡Bienvenido! Elige tus DOS primeros héroes, de cualquier clase — el primero es tu avatar y camina por el Campamento. Las otras clases vienen después, por las cartas de los jefes.",
  "Escolha dois heróis para começar.": "Elige dos héroes para empezar.",
  "Não deu para gravar a escolha. Tente de novo.": "No se pudo guardar la elección. Inténtalo de nuevo.",
  "{a} e {b} são os seus heróis. Boa descida!": "{a} y {b} son tus héroes. ¡Buen descenso!",
  "Escolha <b>{a}</b> de 2": "Elegidos <b>{a}</b> de 2",
  "<b>2 heróis</b> escolhidos — confirme": "<b>2 héroes</b> elegidos — confirma",
  "São dois heróis: tire um para trocar.": "Son dos héroes: quita uno para cambiar.",
  "<b>{a}</b> cartas · ★{b} custa <b>{c}</b>": "<b>{a}</b> cartas · ★{b} cuesta <b>{c}</b>",
  "<b>{a}</b> cartas · ★ no topo": "<b>{a}</b> cartas · ★ al máximo",
  "★ Subir": "★ Subir",
  "Ainda faltam cartas para a próxima estrela.": "Aún faltan cartas para la próxima estrella.",
  "Não deu para subir a estrela agora.": "No se pudo subir la estrella ahora.",
  "★{a} de {b}! {c}": "¡★{a} de {b}! {c}",
  "Já dá: a ★{star} de {nome} custa <b>{custo}</b> cartas — suba na ficha do herói.": "Ya alcanza: la ★{star} de {nome} cuesta <b>{custo}</b> cartas — súbela en la ficha del héroe.",
  "A classe libera sozinha ao juntar as cartas; a estrela é você quem sobe, gastando cartas, aqui ou na ficha do herói. Cai dos chefes; não se troca nem se vende.": "La clase se desbloquea sola al juntar las cartas; la estrella la subes tú, gastando cartas, aquí o en la ficha del héroe. Cae de los jefes; no se intercambia ni se vende.",
  "★ Subir estrela ({a} cartas)": "★ Subir estrella ({a} cartas)",
  "<b>{a}</b> cartas na mão · a ★{b} custa <b>{c}</b>{d}": "<b>{a}</b> cartas en mano · la ★{b} cuesta <b>{c}</b>{d}",
  "★ no topo · <b>{a}</b> cartas na mão · bônus de estrela já contam nos números acima": "★ al máximo · <b>{a}</b> cartas en mano · las bonificaciones de estrella ya cuentan en los números de arriba",
