  "comece hoje": "empieza hoy",
  "Um prêmio por dia, na ordem do calendário — resgate o de hoje e veja os próximos.": "Un premio por día, en el orden del calendario — reclama el de hoy y mira los próximos.",
  "Ver o Quadro de Missões": "Ver el Tablero de Misiones",
  "Um resgate por dia, na ordem: os vinténs crescem a cada resgate, fragmentos no 3º e no 7º, pedras no 5º e uma barra de ouro no 10º, no 20º e no 30º. A ordem segue de onde parou e recomeça no dia 1 de cada mês.": "Un reclamo por día, en orden: los vinténs crecen con cada reclamo, fragmentos el 3º y el 7º, piedras el 5º y una barra de oro el 10º, el 20º y el 30º. El orden sigue desde donde quedó y recomienza el día 1 de cada mes.",
  "<b>{a}</b> resgate(s) neste mês": "<b>{a}</b> reclamo(s) este mes",
  // ---- 08/10: os avisos do aparelho (js/core/notificacoes.js e a chave nas Configurações)
  "SOTERRA — prêmio diário": "SOTERRA — premio diario",
  "O prêmio de hoje está esperando. Entre e resgate!": "El premio de hoy está esperando. ¡Entra y reclámalo!",
  "SOTERRA — o Eco Primordial": "SOTERRA — el Eco Primordial",
