  "SOTERRA — o mundo enterrado": "SOTERRA — el mundo enterrado",
  "Faz três dias que você não desce. O Calabouço do Dia mudou, e o prêmio diário segue na ordem.": "Hace tres días que no bajas. La Mazmorra del Día cambió, y el premio diario sigue en orden.",
  "Avisos do aparelho": "Avisos del dispositivo",
  "Lembretes do prêmio diário (10h), do Eco Primordial (segunda, 12h) e de três dias sem descer. Nada vem de fora do aparelho.": "Recordatorios del premio diario (10 h), del Eco Primordial (lunes, 12 h) y de tres días sin bajar. Nada viene de fuera del dispositivo.",
